# pmid: (type, systems, mechs, direction, summary)
N=["nervous"]; G=["general"]; I=["immune"]
M = {
"42075549": ("meta",N,["induction"],"±","Meta-analysis of 9 knee-OA RCTs (457 pts, 2015-2025). No significant VAS or total WOMAC change at 1 month; WOMAC-pain improved at 18-21 days (MD -1.63) but not at 1 month. Subgroups (amplitude >1 vs <=1 mT; frequency >100 vs <=100 Hz): pain benefit only in a one-study low-amplitude/high-frequency stratum, stiffness/daily activity only in high-amplitude/low-frequency; authors call this hypothesis-generating; pooled MDs below MCID (VAS 19.9 mm, WOMAC-pain 8.7); mostly high risk of bias."),
"35586276": ("meta",N,["induction"],"+","Meta-analysis of 11 OA RCTs (614 pts; 10 knee, 1 hand) since 2009: PEMF versus control gave SMD 0.71 for pain (95% CI 0.08-1.34), 1.34 for stiffness and 1.52 for function. Abstract reports no parameter moderator analysis; comparators include non-sham controls."),
"32508140": ("meta",N,["induction"],"±","Meta-analysis of 13 knee-OA RCTs (914 pts): overall pain SMD -0.41 (p=0.009), activity SMD -0.45 (n.s.). Restricting to placebo-controlled trials gave larger effects; trials against alternative therapies showed no difference; longer follow-up correlated with smaller differences."),
"31583420": ("meta",N,["induction"],"0","Meta-analysis of 8 RCTs (421 pts) of classical PEMF versus placebo in knee OA: function improved (WMD -5.28) but WOMAC-pain (WMD -1.06, CI -2.30 to 0.17), VAS pain (WMD -0.88, CI -2.06 to 0.31), stiffness and total WOMAC were not significant."),
"30552258": ("meta",N,["induction"],"±","Meta-analysis of 12 sham-controlled OA RCTs: knee-OA pain SMD -0.54 (CI -1.04 to -0.04) and hand-OA pain SMD -2.85 (single trial), none for cervical OA. Sensitivity analysis found sessions of <=30 min better than >30 min; adverse events not different from sham."),
"23973142": ("meta",N,["induction"],"0","Meta-analysis of 7 small sham-controlled trials (459 knees) of low-frequency (<=100 Hz) sub-sensory PEMF/pulsed electrical stimulation in knee OA: function SMD 0.22 (CI 0.04-0.41), pain SMD 0.08 (CI -0.17 to 0.32, I2 43%); evidence rated low/very low."),
"21938735": ("review",N,["induction"],"0","Systematic review of 11 double-blind sham-controlled trials of whole-body low-frequency PEMF mats (n 12-71, <=12 weeks, flux density 3.4-200 uT); only sporadic positive effects without independent confirmation, so evidence judged insufficient."),
"19479151": ("meta",N,["induction"],"0","Meta-analysis of 9 placebo-controlled knee-OA trials (483 pts): pain WMD 0.2 (CI -0.4 to 0.8) and stiffness not significant, ADL and pooled function scores improved (SMD 0.4). Sensitivity analysis and meta-regression found only non-significant differences between treatment protocols."),
"17587446": ("meta",N,["induction"],"±","Meta-analysis of 36 placebo-controlled physical-agent trials in knee OA (2434 pts): PEMF reduced pain by 6.9 mm VAS (CI 2.2-11.6, n=487) versus 18.8 mm for TENS and 17.7 mm for laser, i.e. below the usual clinically relevant range."),
"35077249": ("meta",N,["induction"],"±","Meta-analysis of 14 low-back-pain trials (618 pts): PEMF versus placebo pain SMD -1.01 (CI -1.42 to -0.60) and versus other therapy SMD -0.36; chronic LBP SMD -0.60 (I2 67%) but acute LBP not significant (SMD -0.46, CI -0.99 to 0.07); no function benefit."),
"32606905": ("review",N,["induction"],"+","Systematic review of 21 musculoskeletal-pain RCTs (2009-2018) concluding that low-intensity, low-frequency (1-100 Hz) pulsed fields are most used; full text lists parameters of individual trials (e.g. whole-body 40 uT mean, 0.1-64 Hz in fibromyalgia; 0-150 uT at 33.3 Hz null; 100 uT 1-80 Hz non-pulsed ELF positive), used here as secondary source."),
"42146884": ("review",N,["induction"],"±","Narrative review of 8 RCTs (2015-2025) comparing low-intensity PEMF with high-intensity repetitive peripheral magnetic stimulation (10-50 mT, trains to 100 Hz, visible contractions); reports ~2-3 VAS point benefits, larger short-term effects at >=10 mT, rPMS faster than PEMF. Its table lists Bagnato as low-frequency although the trial used 27.12 MHz pulsed RF; intensity values are device-specific and not comparable."),
"42652114": ("review",N,["induction"],"±","Systematic review (28 studies, 1060 pts) of dosimetry in EMTT and PEMF for musculoskeletal pain. High-intensity, fast-edge protocols (EMTT 80 mT, 3 Hz, 20 min x 8; dB/dt stated as >60 kT/s; HE-PEMF 50 mT) gave robust effects, while <5 mT protocols (0.1, 2, 5 mT) were generally indistinguishable from sham or active controls; narrative synthesis, no meta-analysis."),
"38102884": ("meta",N,["induction"],"±","Systematic review/meta-analysis of peripheral magnetic stimulation for chronic peripheral neuropathic pain (23 studies, 15 RCTs): pain reduced by MD -1.64 NRS within 0-1 month (CI -2.73 to -0.56, I2 94%, very low quality) but not at 1-3 or >3 months; 4 of 9 placebo-controlled RCTs significant."),
"15846703": ("review",N,["induction"],"±","Cochrane review of electrotherapy for neck disorders (14 comparisons, 525 pts): limited evidence that low- or high-frequency PEMF gives immediate pain relief only in chronic mechanical neck disorders; pooling impossible due to heterogeneity."),
"42227300": ("review",N,["induction"],"0","Systematic review of 7 RCTs of BEMER-type PEMF for musculoskeletal pain: only 1 of 4 sham-controlled studies found superiority over sham; protocols highly heterogeneous; no evidence of an effect beyond placebo."),
"25962809": ("review",N,["radical","icr","endogenous"],"±","Author-perspective review of 30 years of ELF-field effects on opioid-related behaviour from snails to humans (including attenuation of opioid analgesia in mice, analgesia from shielding and from specific pulsed fields, EEG/fMRI work); explicitly not a balanced review."),
"22451021": ("rct",N,["camno"],"+","Double-blind sham-controlled pilot (n=34, early knee OA, baseline VAS >=4): active signal lowered VAS by 50 +/- 11% from day 1 to day 42 (p<0.001) with no significant change in sham; overall decrease nearly threefold that of sham. Device parameters not in abstract (secondary source quotes 6.8 MHz, 30 G, 15 min twice daily for 2 weeks)."),
"26705327": ("rct",N,["induction"],"+","Double-blind placebo-controlled RCT (60 completers, knee OA, 12 h/day for 1 month) with a 27.12 MHz pulsed-RF patch (1000 Hz pulse rate, 100 us bursts): VAS fell 25.5% versus 3.6% on placebo (effect size -0.73, CI -1.24 to -0.19), WOMAC-pain -0.61, total WOMAC -0.34 (CI -0.85 to 0.17, n.s.); pressure pain threshold rose; 26% of treated patients stopped analgesics."),
"15979009": ("rct",N,["induction"],"0","Double-blind placebo-controlled RCT (n=83 knee OA, 2 h/day, 5 days/week for 6 weeks): both groups improved within-group, but between-group analysis showed no benefit on WOMAC pain, ADL or stiffness; only patients under 65 showed a stiffness effect."),
"11900312": ("rct",N,["induction"],"0","Randomised double-blind placebo-controlled 6-week trial of a unipolar low-frequency PEMF device (Medicur) in 75 knee-OA patients: no significant active-versus-sham difference at study end, though paired within-group analysis improved only in the active group (WOMAC global p=0.018)."),
"16770449": ("rct",N,["endogenous"],"+","Double-blind placebo-controlled acute 30-min exposure (<=400 uT peak, <3 kHz specific pulsed field) in rheumatoid arthritis (n=13) and fibromyalgia (n=18): McGill pain rating index fell more than with sham (interaction F=5.09 in RA, F=16.2 in FM); anxiety unchanged. Small samples."),
"19920724": ("rct",N,["induction"],"+","Double-blind sham-controlled RCT of whole-body low-frequency PEMF in 56 women with fibromyalgia (30 min twice daily for 3 weeks): FIQ, VAS pain, BDI and SF-36 improved at the end of therapy; sham also improved in several measures, and only some gains persisted at 12 weeks (secondary source: mean 40 uT, 0.1-64 Hz; VAS 73.3 to 38.1 versus 68.4 to 63.4)."),
"15986086": ("rct",N,["induction"],"+","Double-blind sham-controlled RCT (n=34 cervical OA): whole-body mat PEMF, 30 min twice daily for 3 weeks, lowered pain (p<0.001) and improved ROM and neck-pain/disability scores with no change in the placebo group; amplitude and frequency not given in abstract."),
"29616749": ("rct",N,["induction"],"th","Single-blinded placebo-controlled trial (106 patients, discopathic low back pain) comparing 10 mT/50 Hz, 5 mT/50 Hz, 49.2 uT/195 Hz and two shams: only the 10 mT, 50 Hz, 20 min group showed significant improvement in pain, range of motion and function, mostly short-lived. The only within-trial field-amplitude comparison in a pain RCT."),
"30177406": ("rct",N,["induction"],"±","RCT (n=50, chronic non-specific LBP) of 50 Hz, ~2 mT (20 G) PEMF added to physiotherapy for 12 sessions over 4 weeks: reports between-group benefit in pain, disability and ROM, but the stated pain MD 1.52 has a CI of -0.34 to 3.35 that includes zero, contradicting the claim; a review quotes the 2 mT LBP trial as no better than control."),
"31575112": ("rct",N,["induction"],"0","Double-blind sham-controlled RCT (n=42, chronic LBP) of PEMF plus exercise: improvement came faster in the PEMF group at week 3 but the sham group caught up by week 6, with no between-group difference at weeks 6 and 13."),
"29950893": ("rct",N,["induction"],"th","Double-blind sham-controlled pilot (n=36, post-lumbar-surgery pain) of a pulsed-RF device (27.12 MHz) at two pulse widths, self-treatment twice daily for 60 days: back pain fell 40.2% with 42 us, 18.6% with 38 us and 25.6% with sham; leg pain 45.0% / 17.0% / 24.5%; treatment-minus-sham differences did not reach conventional significance."),
"33923872": ("rct",N,["induction"],"+","Randomised crossover-type trial (n=64, chronic LBP with neuropathic component): 10 sessions of 20 min over 2 weeks of low-energy pulsed electromagnetic signals lowered VAS and DN4 only in the active-device condition; field parameters not given in abstract."),
"28893387": ("rct",N,["induction"],"0","Randomised pilot (n=75 service members, chronic LBP, usual care +/- PEMF): improved physical/mental quality of life but non-significant pain and disability improvements; anxiety scores were higher in the PEMF arm; no sham control."),
"29709070": ("rct",N,["induction"],"0","Randomised crossover (n=108 women with fibromyalgia, 12 weeks active versus sham BEMER): VAS pain fell 12 mm on active and 11 mm on sham, per-protocol analysis showed no active-versus-sham difference in pain, stiffness or FIQ (secondary source: 0-150 uT, 33.3 Hz)."),
"24308025": ("rct",N,["induction"],"+","Double-blind placebo-controlled trial (28 stimulated, 26 sham, fibromyalgia) of very low-intensity 8 Hz pulsed magnetic stimulation, 8 weekly sessions: pressure pain thresholds improved from the first session, daily activity, chronic pain and sleep after ~6 weeks; no change in depression, fatigue, headache or serotonin."),
"36465321": ("rct",N,["induction"],"+","Single-blind pilot (n=21 women, fibromyalgia) of low-energy PEMF versus placebo at 0, 4 and 8 weeks: VAS pain fell 48 versus 16.8 mm (difference-in-difference -31.2, p<0.01) and widespread pain index improved; FIQ and SF-36 trended. Very small and not double-blind."),
"24280467": ("rct",N,["induction"],"+","Single-blind RCT (25 per arm, hand OA) of magnetotherapy at 25 Hz, 450 pulses/s, 5-80 G for 20 min/day over 10 days plus exercise versus sham plus exercise: pain at rest and motion, stiffness, function and SF-36 pain favoured active (p<0.001)."),
"18585071": ("rct",N,["induction"],"0","Randomised double-blind sham-controlled trial (61 patients, painful diabetic polyneuropathy; Viofor JPS, 20 min/day, 5 days/week for 3 weeks): VAS fell 73 to 33 mm active but also 69 to 41 mm sham, with no between-group difference at any time."),
"18777606": ("rct",N,["induction"],"±","Randomised double-blind placebo trial (36 hands, carpal tunnel) of combined static and time-varying fields 4 h/day for 2 months: VAS and PGIC not significant, but neuropathic pain scale composite fell 42% versus 24% (p=0.042); open-label extension suggested electrophysiological gains."),
"17333120": ("rct",N,["induction"],"th","Double-blind pilot after knee-cartilage arthroscopy (31 completers): 1.5 mT active versus a 0.05 mT control field, 6 h/day for 90 days; KOOS higher at 90 days (p<0.05) and NSAID use 26% versus 75% (p=0.015). A rare within-trial B contrast, but the 'control' is a low-dose field rather than zero."),
"18506512": ("rct",N,["camno"],"+","Double-blind placebo-controlled pilot (42 women, breast augmentation; 80 breasts analysed) of a portable PEMF device: VAS pain fell about threefold faster than sham by postoperative day 3 (p<0.001) and analgesic use fell correspondingly; device waveform not in abstract."),
"22297104": ("rct",N,["induction"],"+","Double-blind placebo-controlled study (n=70, plantar fasciitis) of a wearable pulsed-RF device worn overnight: morning VAS 40% lower at day 7 versus 7% in control (p=0.03), evening VAS 30% versus 19% (n.s.). Radiofrequency, not low-frequency induction."),
"15172106": ("rct",N,["endogenous"],"+","Two double-blind studies in healthy volunteers (n=39 and n=31): 30 min of a specific pulsed magnetic field raised thermal pain thresholds versus sham (with a condition x gender interaction) without changing sensory thresholds; authors discuss placebo; field amplitude not in abstract."),
"23480978": ("rct",N,["induction"],"0","Randomised study (45 patients, chronic mechanical neck pain) in which a whole-body PEMF arm (5-25 Hz, 5-70 uT, per the Paolucci review) did not reduce pain or disability significantly; PubMed shows no abstract, so parameters are secondary."),
"9111740": ("animal",N,["endogenous"],"th","Land snail Cepaea: 15-min exposure to a frequency-modulated ~100 uT-peak pulsed field (Cnp) induced analgesia and increased enkephalinase-inhibitor analgesia; naloxone attenuated but did not abolish it, and two other waveforms were ineffective, showing waveform specificity."),
"9213364": ("animal",N,["endogenous"],"th","Cnp-induced analgesia in Cepaea was reduced but not eliminated by naloxone, mu antagonists (naloxazine, beta-funaltrexamine) and delta antagonists, and unaffected by the kappa antagonist nor-binaltorphimine, indicating partial delta/mu opioid mediation."),
"7601344": ("animal",N,["icr","endogenous"],"th","Snail opioid-analgesia inhibition depended nonlinearly on 60 Hz amplitude (0-547 uT), showed inhibitory frequency windows (30-35, 60-90, 120, 240 Hz at 141 uT, 10-240 Hz scanned) and depended on the static field, arguing for a direct (resonance-like) detection rather than induced currents."),
"9096848": ("animal",N,["icr","radical"],"th","With static and AC fields set to Ca2+ parametric-resonance predictions at 30, 60 and 120 Hz, snail opioid-analgesia reduction was frequency-independent and larger in light than dark, which the authors read as direct field detection rather than induced current."),
"10797457": ("animal",N,["icr","radical"],"±","Snail ELF fields (141-414 uT peak) chosen by Lednev's parametric resonance model for Ca2+ either reduced, left unchanged, or increased opioid analgesia as predicted; K+ settings increased it with glibenclamide antagonism; all effects needed light."),
"9795129": ("animal",N,["camno","endogenous"],"±","In Cepaea, a 60 Hz 141 uT-peak field (15 min) reduced enkephalinase-induced analgesia; this inhibition was reduced by the NOS inhibitor L-NAME and enhanced by the NO donor SNP at doses inactive alone, implicating NO/NOS in the field effect."),
"1933319": ("animal",N,["endogenous","effectors"],"±","In Cepaea, 2 h of a 1.0 G rms 60 Hz field reduced morphine analgesia; the effect was reduced by PKC inhibitors (H-7, H-9) and enhanced by a PKC activator, whereas the calmodulin inhibitor W-7 had no effect, implicating PKC."),
"2452251": ("animal",N,["vgcc","endogenous"],"±","Snail 0.5 Hz rotating fields (1.5-8.0 G, 15-30 min) reduced mu- and kappa-opiate analgesia and stress-induced analgesia like naloxone; dihydropyridine and non-DHP Ca2+ channel blockers reduced, and the DHP agonist BAY K8644 increased, the field effect."),
"8402190": ("animal",N,["endogenous"],"±","Snails given daily 30-min exposure to a 60 Hz 1.0 G (0.1 mT) field developed hypoalgesia resembling that from repeated naloxone injections, consistent with an opioid-antagonist-like action of the field."),
"14698475": ("animal",N,["endogenous"],"+","In CF-1 mice a 100 uT specific pulsed ELF field (Cnp) prolonged hot-plate latency to an extent equivalent to morphine 5 mg/kg and offset morphine-induced hyperactivity."),
"15672364": ("animal",N,["radical","endogenous"],"+","Mice placed 1 h/day for 10 days in a mu-metal shielded box (ambient field reduced) developed analgesia peaking on days 4-6 (comparable to morphine 5 mg/kg) that was abolished by naloxone."),
"11798436": ("animal",N,["radical","endogenous"],"±","Replicated in Pisa and London: mu-metal shielding reduced stress-induced analgesia in mice, but nulling the static field with Helmholtz coils or copper-shielding the electric field did not; the authors attribute the effect to loss of the very weak time-varying ambient component."),
"18583276": ("animal",N,["radical"],"th","The analgesia induced by magnetic shielding in mice was abolished by UV (405 nm) or blue (465 nm) light but not red light; the blue-light threshold was about 12% of facility light (~5 x 10^16 photons/s/m2), resembling photoreceptor-based magnetoreception."),
"21381048": ("animal",N,["induction","radical"],"th","In shielded mice, adding 30 or 120 Hz fields of 25-500 nT peak attenuated the shielding analgesia (120 Hz at all amplitudes tested; 30 Hz from 50 nT); at constant B x f = 6000 nT-Hz (12.5-100 Hz) the attenuation was constant, so the detector tracks the nT-Hz (dB/dt-like) product, with a threshold at or below ~1000 nT-Hz."),
"22608074": ("animal",N,["endogenous","vgcc"],"+","Custom magnetic stimulator reversed paclitaxel-induced mechanical hyperalgesia in mice; the effect was blocked by naloxone and combined synergistically with pregabalin (Ca2+ channel ligand). Stimulus parameters not given in abstract."),
"29023859": ("animal",N,["endogenous"],"th","Rats made tolerant to morphine (10 mg/kg for 8 days) and exposed 30 min to 50 Hz at 1, 50 or 100 uT, or 0.5/6/12/30 Hz at 100 uT: tolerance was prevented by 50 Hz 1 uT or 30 Hz 100 uT immediately before morphine and by 50 Hz 100 uT after it, but not by exposure 30 min after injection; the abstract does not report the other conditions as effective."),
"28836499": ("animal",N,["endogenous"],"+","Rats exposed to 50 Hz fields for 30 min/day for 15 days showed maximum effect of a 5 mT field at day 7: morphine (5 mg/kg) analgesia was enhanced and morphine tolerance reduced, i.e. the opposite sign to the opioid-attenuating snail/mouse literature."),
"27901476": ("animal",N,["effectors"],"+","Rat chronic-constriction-injury model: PEMF lengthened paw withdrawal latency and threshold and promoted nerve regeneration, but did not restore the CCI-reduced HCN1/HCN2 mRNA, so HCN channel expression does not explain the analgesia; field parameters are not in the abstract."),
"24937769": ("invitro",N,["vgcc"],"+","Cultured neonatal rat DRG neurons exposed to 50 Hz, 1 mT PEMF for 2 h showed raised intracellular Ca2+ and Bdnf mRNA via L-type VGCC influx (not mobilisation) and Erk activation, as shown with channel and Erk inhibitors."),
"17568617": ("animal",N,["effectors"],"+","Mice in a validated whole-body static field showed fewer acetic-acid/MgSO4 writhes, less formalin-phase I/II licking and less carrageenan/RTX hyperalgesia; the effect disappeared in resiniferatoxin-pretreated animals, implicating capsaicin-sensitive (TRPV1) fibres. Static field, not pulsed."),
"17654477": ("animal",N,["magnetite"],"+","Mouse writhing test: analgesia depended on the spatial arrangement of permanent magnets; an optimised arrangement achieved over 80% inhibition. Static field only."),
"23737187": ("animal",N,["magnetite"],"th","Static-field mouse study: inhomogeneous (3-477 mT) and homogeneous (145 mT) fields gave 62-64% inhibition of writhing; the lateral field gradient between exposed and sham sides accounted for most of the effect (91% and 54% inhibition), pointing to gradient rather than absolute B."),
"23134601": ("animal",N,["endogenous","magnetite"],"+","Snail Helix: homogeneous and inhomogeneous static fields raised the thermal nociceptive threshold by 29-46% after 20-40 min; homogeneous exposure antagonised the hypoalgesic effect of naloxone, implying partial opioid involvement."),
"10228567": ("theory",G,["camno","induction"],"th","Binding-kinetics model predicting the frequency window of a target pathway; a pulsed RF waveform retuned by burst duration matched the clinical signal in Ca2+/calmodulin-dependent myosin phosphorylation, neurite outgrowth and bone repair with a tenfold lower peak amplitude (about 800-fold lower average amplitude), supporting a waveform/spectral rather than amplitude driver."),
"40824993": ("animal",N,["induction"],"th","Coil-design study: a four-leaf rhombus coil driven by a 25 V rectangular pulse with 200 us rise time elicited compound muscle action potentials by rat sciatic-nerve magnetic stimulation, showing that a ~24-25 V drive can reach nerve threshold when the field gradient is optimised. B and E not given in abstract."),
"19656823": ("human",N,["endogenous"],"+","fMRI study in healthy volunteers: exposure to a low-frequency pulsed magnetic field altered the pre/post activation pattern to acute thermal pain in right insula, anterior cingulate and bilateral hippocampus/caudate versus sham; field amplitude not in abstract."),
"20142869": ("rct",N,["induction"],"+","Randomised trial (n=30, diabetic polyneuropathy): low-power 600 or 800 Hz PEMF for 30 min on 12 consecutive days reduced pain and improved nerve-conduction latency and velocity versus usual care; control was not sham."),
}
